    return { kind: "plugin-manifest", path };
  }
  if (/\/skills\/[^/]+\/SKILL\.md$/.test(path)) {
    return { kind: "skill", path };
  }
  if (/\/agents\/[^/]+\.md$/.test(path)) {
    return { kind: "agent", path };
  }
  return null;
}

